def run_generation(dry_run: bool = False) -> None:
    from config import RAW_TEXT_DIR, MANIFEST_PATH
    from watchdog.dataset_manager import (
        init_manifest, add_entry, ManifestEntry, load_manifest, print_stats,
        CATEGORY_TEXTUAL_CORPUS, LABEL_SYNTHETIC,
    )

    init_manifest(MANIFEST_PATH)
    existing = load_manifest(MANIFEST_PATH)
    already_logged_paths = set(existing["local_path"]) if not existing.empty else set()

    written, skipped = 0, 0

    for i, sample in enumerate(SYNTHETIC_SAMPLES, 1):
        save_path = RAW_TEXT_DIR / sample["filename"]
        rel_path = str(save_path.relative_to(Path.cwd())) if save_path.is_absolute() else str(save_path)

        if rel_path in already_logged_paths:
            logger.info(f"[{i}/{len(SYNTHETIC_SAMPLES)}] Already logged, skipping: {sample['filename']}")
            skipped += 1
            continue

        logger.info(f"[{i}/{len(SYNTHETIC_SAMPLES)}] {sample['genre']:8s} — {sample['topic']}")

        if dry_run:
            logger.info(f"  [dry-run] would write {len(sample['text'])} chars to {rel_path}")
            continue

        save_path.write_text(sample["text"], encoding="utf-8")

        entry = ManifestEntry(
            sample_id=str(uuid.uuid4()),
            local_path=rel_path,
            source_url=f"llm-generated:claude-sonnet-5:{sample['genre']}:{sample['filename']}",
            media_type="text",
            category=CATEGORY_TEXTUAL_CORPUS,
            label=LABEL_SYNTHETIC,   # certain by construction — no human review needed
            publisher_name="N/A (LLM-generated)",
            scraped_at=datetime.now(timezone.utc).isoformat(),
            notes=(
                f"Synthetic {sample['genre']} sample, topic: {sample['topic']}. "
                f"Generated per §3.9 'vs LLM copy' methodology — label certain "
                f"by construction, not reviewed via --label."
            ),
        )
        add_entry(entry, path=MANIFEST_PATH)
        logger.info(f"  \u2713 Written + logged: {sample['filename']} (label=1, certain)")
        written += 1

    print("\n" + "=" * 65)
    print("  SYNTHETIC CORPUS GENERATION COMPLETE")
    print("=" * 65)
    print(f"  Newly written:  {written}")
    print(f"  Already had:    {skipped}")
    print(f"  News-style:     {sum(1 for s in SYNTHETIC_SAMPLES if s['genre'] == 'news')}")
    print(f"  Ad copy:        {sum(1 for s in SYNTHETIC_SAMPLES if s['genre'] == 'ad_copy')}")
    print("=" * 65)

    if not dry_run:
        print_stats(MANIFEST_PATH)


def main():
    parser = argparse.ArgumentParser(
        description="Generate + log the synthetic (label=1) side of the Textual Corpus (§3.9)"
    )
    parser.add_argument("--dry-run", action="store_true",
                       help="Preview without writing files or touching the manifest")
    args = parser.parse_args()
    run_generation(dry_run=args.dry_run)


if __name__ == "__main__":
    main()
